PAGE='''<!doctype html><html><head><meta charset="utf-8"><title>Local Film Pipeline</title><style>body{max-width:1100px;margin:1em auto;font:16px system-ui;padding:0 1em;background:#101622;color:#e8edf3}label{display:block;margin:.45em 0 .2em}input,textarea,select,button{font:inherit;padding:.6em;border-radius:5px;border:1px solid #637085}textarea,input{box-sizing:border-box;width:100%;background:#1e293b;color:white}button{cursor:pointer;background:#80c0f0;color:#101622;margin:.6em .4em .6em 0}small{color:#b5c5d8}.columns{display:grid;grid-template-columns:1fr 1fr;gap:1em}@media(max-width:700px){.columns{grid-template-columns:1fr}}details{margin:.6em 0}#jobList{max-height:14em;overflow:auto}button:disabled{opacity:.55;cursor:not-allowed}pre{max-height:18em;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:#1e293b;padding:1em}.log-panel{background:#111d2c;border:1px solid #3a4b61;border-radius:10px;overflow:hidden;margin:1em 0}.log-heading,.log-tools{display:flex;align-items:center;flex-wrap:wrap;gap:.6em 1em;padding:.6em 1em}.log-heading{justify-content:space-between;border-bottom:1px solid #344155}.log-heading h3{margin:0}.log-heading span,#logNote{font-size:.8em;color:#afc2d8}.log-tools label{display:flex;align-items:center;gap:.4em;margin:0;font-size:.85em}.log-tools select{background:#1e293b;color:#e8edf3;max-width:100%;padding:.35em}.log-tools button{font-size:.85em;padding:.4em .6em;margin:0}.follow-label input{width:auto;margin:0;accent-color:#80c0f0}#logs{height:20em;max-height:50vh;overflow:auto;overscroll-behavior:contain;background:#0a111b;font:12px/1.65 Consolas,monospace;padding:.7em .3em;scrollbar-color:#4d6380 #0a111b}.log-line{padding:.12em .8em;border-left:3px solid transparent;white-space:pre-wrap;overflow-wrap:anywhere}.log-warning{color:#ffdc8b;border-color:#dba743;background:#392d1738}.log-error{color:#ffb3b9;border-color:#ff6e7c;background:#4c202a55}.log-progress{color:#8de0cf;border-color:#4aa994}.log-info{color:#bdcce0}.log-empty{padding:1em;color:#91a5bd}#logNote{margin:.7em 1em}#statusSummary{padding:.7em 1em;border-radius:6px;background:#1b2b3e;font-weight:600}</style></head><body><h1>Local Film Pipeline</h1><p>Create a local job. Models run on this computer; completed videos and review evidence are saved in a new job folder.</p><section><h2>Job queue</h2><p>Jobs run one at a time. You can cancel a running or waiting job below.</p><div id="queueList">Loading queue...</div></section><form id="form"><div class="columns"><div><label>Creative brief</label><textarea name="brief" required rows="3" placeholder="A mysterious transmission arrives in a quiet room."></textarea></div><div><label>Script</label><textarea name="script" required rows="5" placeholder="The signal came from the other side of the door."></textarea></div></div><label for="segmentInstructions">Instructions for every segment</label><textarea id="segmentInstructions" name="segment_instructions" rows="2" maxlength="2000" placeholder="Camera stays static. No zoom, pan, tilt, or change of framing."></textarea><small>Copied unchanged into every opening and continuation prompt. Put ongoing rules here; put one-time actions in the brief. Models can still miss instructions; review the result.</small><label for="seedMode">Video seed</label><select id="seedMode" name="seed_mode"><option value="random" selected>Random for each new job</option><option value="custom">Use my seed</option></select><input id="seedValue" name="seed" type="number" min="0" max="4294967295" step="1" placeholder="Enter a whole-number seed" disabled><small>The chosen base seed appears in job status and saved settings. Matching the seed alone does not reproduce a video if its prompts or settings change.</small><details><summary>Style, references, timing and output settings</summary><label>Visual style</label><input name="style" required placeholder="Your visual style"><label>Character reference image paths (optional; one per line)</label><textarea name="references" rows="2" placeholder="F:\\images\\character.png"></textarea><label>Object reference image path (optional)</label><input name="object_reference" placeholder="F:\\images\\graphics-card.jpg"><label>Object description</label><input name="object_description" placeholder="The graphics card being installed"><small>Object references are experimental; review the generated object and continuity.</small><label>Silence before each speech (seconds)</label><input name="speech_before_seconds" type="number" value="1" min="0" max="30" step="0.1"><label>Silence after each speech (seconds)</label><input name="speech_after_seconds" type="number" value="1" min="0" max="30" step="0.1"><label>Local music file path (optional)</label><input name="music" placeholder="F:\\audio\\music.wav"><small>Music is mixed quietly underneath speech. Leave empty for narration only.</small><label>Output width and height</label><input name="width" type="number" value="1080" min="256" max="3840" step="2"><input name="height" type="number" value="1920" min="256" max="3840" step="2"><label>Frame rate</label><select name="fps"><option>24</option><option>25</option><option>30</option></select><label>Target seconds (optional; 0 = fit narration)</label><input name="duration_seconds" type="number" value="0" min="0" max="180" step="0.1"></details><button type="submit">Start job</button><button type="button" id="plan">Make editable plan only</button></form><p id="message"></p><details><summary>Recent jobs and live logs</summary><div id="jobList"></div></details><section id="job" hidden><h2>Selected job</h2><p id="statusSummary" role="status"></p><details><summary>Full job details</summary><pre id="status"></pre></details><div class="log-panel"><div class="log-heading"><h3>Live activity</h3><span id="logUpdated">Waiting for update</span></div><div class="log-tools"><label for="logSource">Source <select id="logSource"><option value="comfy">ComfyUI (shared)</option><option value="worker">Job worker</option><option value="planner">Shot planner</option></select></label><label for="logFilter">Show <select id="logFilter"><option value="all">All messages</option><option value="issues">Warnings &amp; errors</option></select></label><label class="follow-label"><input id="followLog" type="checkbox" checked> Follow latest</label><button id="copyLog" type="button">Copy log</button></div><div id="logs" role="log" aria-label="Recent process output" aria-live="off" tabindex="0"><div class="log-empty">Waiting for log output?</div></div><p id="logNote"></p></div><button id="refresh">Refresh</button><button id="loadPlan">Open plan editor</button><button id="run">Run / resume</button><div id="editor" hidden><label>Edit shot plan JSON</label><textarea id="planText" rows="18"></textarea><button id="savePlan">Save plan</button><small>Save edits before running. Do not change a plan after its voice or video generation has begun.</small></div></section><script src="/log-view.js"></script><script>
let current='';document.querySelector('#seedMode').onchange=()=>{let custom=document.querySelector('#seedMode').value==='custom';document.querySelector('#seedValue').disabled=!custom;document.querySelector('#seedValue').required=custom};async function api(url,opts){let r=await fetch(url,opts);let j=await r.json();if(!r.ok)throw Error(j.error||r.status);return j}function payload(){let f=new FormData(document.querySelector('#form'));return {seed_mode:f.get('seed_mode'),seed:f.get('seed_mode')==='custom'?Number(f.get('seed')):null,segment_instructions:f.get('segment_instructions'),brief:f.get('brief'),script:f.get('script'),style:f.get('style'),references:f.get('references').split('\\n').map(x=>x.trim()).filter(Boolean),music:f.get('music').trim(),object_reference:f.get('object_reference').trim(),object_description:f.get('object_description').trim(),speech_before_seconds:Number(f.get('speech_before_seconds')),speech_after_seconds:Number(f.get('speech_after_seconds')),width:Number(f.get('width')),height:Number(f.get('height')),fps:Number(f.get('fps')),duration_seconds:Number(f.get('duration_seconds'))}}async function create(mode){try{let j=await api('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request:payload(),mode})});current=j.job_id;document.querySelector('#job').hidden=false;document.querySelector('#message').textContent='Job created: '+current;await refresh()}catch(e){document.querySelector('#message').textContent=e.message}}document.querySelector('#form').onsubmit=e=>{e.preventDefault();create('run')};document.querySelector('#plan').onclick=()=>create('plan');async function refresh(){await refreshJobs();if(!current)return;try{let selected=current;let s=await api('/api/jobs/'+selected);if(selected!==current)return;document.querySelector('#status').textContent=JSON.stringify(s,null,2);let complete=Object.values(s.segments||{}).filter(x=>x.status==='complete').length;document.querySelector('#statusSummary').textContent=s.job_id+' ? '+s.status.replaceAll('_',' ')+' ? '+complete+' segments saved';let logs=await api('/api/jobs/'+selected+'/logs');if(selected===current)updateLog(logs,selected)}catch(e){document.querySelector('#message').textContent=e.message}}document.querySelector('#refresh').onclick=refresh;document.querySelector('#run').onclick=async()=>{try{await api('/api/jobs/'+current+'/run',{method:'POST'});await refresh()}catch(e){document.querySelector('#message').textContent=e.message}};document.querySelector('#loadPlan').onclick=async()=>{try{let p=await api('/api/jobs/'+current+'/plan');document.querySelector('#planText').value=JSON.stringify(p,null,2);document.querySelector('#editor').hidden=false}catch(e){document.querySelector('#message').textContent=e.message}};document.querySelector('#savePlan').onclick=async()=>{try{await api('/api/jobs/'+current+'/plan',{method:'PUT',headers:{'Content-Type':'application/json'},body:document.querySelector('#planText').value});document.querySelector('#message').textContent='Plan saved.'}catch(e){document.querySelector('#message').textContent=e.message}};async function refreshJobs(){try{let jobs=await api('/api/jobs');let queued=jobs.filter(j=>['queued','starting','planning','voicing','waiting_for_gpu','rendering','assembling','checking','waiting_for_turn','cancelling'].includes(j.status));let queue=document.querySelector('#queueList');queue.replaceChildren();if(!queued.length){let note=document.createElement('span');note.textContent='No running or waiting jobs. ';queue.append(note);let c=document.createElement('button');c.type='button';c.disabled=true;c.textContent='Cancel job';c.title='Available when a job is active or waiting';queue.append(c)}for(let j of queued){let row=document.createElement('p');row.append(document.createTextNode((j.position?'Queue #'+j.position:j.status)+' - '+j.job_id+' '));let c=document.createElement('button');c.type='button';c.textContent=j.status==='queued'?'Cancel queued job':'Cancel running job';c.disabled=j.status==='cancelling';if(c.disabled)c.textContent='Cancelling...';c.onclick=async()=>{try{await api('/api/jobs/'+j.job_id+'/cancel',{method:'POST'});document.querySelector('#message').textContent='Cancellation requested: '+j.job_id;await refresh()}catch(e){document.querySelector('#message').textContent=e.message;await refreshJobs()}};row.append(c);queue.append(row)}let box=document.querySelector('#jobList');box.replaceChildren();for(let j of jobs.slice().reverse().slice(0,30)){let row=document.createElement('p');let b=document.createElement('button');b.type='button';b.textContent=j.job_id;b.onclick=()=>{current=j.job_id;document.querySelector('#job').hidden=false;refresh()};row.append(b);row.append(document.createTextNode(' '+j.status+(j.position?' (queue #'+j.position+')':'')));box.append(row)}}catch(e){document.querySelector('#message').textContent=e.message}}refreshJobs();setInterval(refresh,5000)
</script></body></html>'''

class Handler(BaseHTTPRequestHandler):
 def send_json(self,obj,status=200):
  data=json.dumps(obj,ensure_ascii=False).encode();self.send_response(status);self.send_header('Content-Type','application/json; charset=utf-8');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
 def job(self,ident):
  if not ident or not all(c.isalnum() or c=='-' for c in ident):raise ValueError('Invalid job id')
  p=JOBS/ident
  if not (p/'state.json').exists():raise FileNotFoundError('Job not found')
  return p
 def body(self):
  n=int(self.headers.get('Content-Length','0'))
  if n>2_000_000:raise ValueError('Request too large')
  return json.loads(self.rfile.read(n))
 def do_GET(self):
  try:
   path=urllib.parse.urlsplit(self.path).path;parts=path.strip('/').split('/')
   if path=='/log-view.js':
    data=(ROOT/'local_film'/'log_view.js').read_bytes();self.send_response(200);self.send_header('Content-Type','text/javascript; charset=utf-8');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data);return
   if path=='/':
    data=PAGE.encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data);return
   if path=='/api/form-defaults':
    defaults=JOBS/'form-defaults.json';self.send_json(load(defaults) if defaults.is_file() else {});return
   if parts==['api','jobs']:
    self.send_json(QUEUE.list());return
   if len(parts)>=3 and parts[:2]==['api','jobs']:
    job=self.job(parts[2])
    if len(parts)==4 and parts[3]=='logs':
     sources=[]
     for ident,title,path,shared in [('comfy','ComfyUI',JOBS/'comfy-server.log',True),('worker','Job worker',job/'worker.log',False),('planner','Shot planner',job/'planner.log',False)]:
      sources.append({'id':ident,'title':title,'shared':shared,'lines':log_tail(path)})
     self.send_json({'sources':sources,'text':'\n\n'.join('--- '+s['title']+' ---\n'+'\n'.join(s['lines']) for s in sources if s['lines'])});return
    self.send_json(load(job/'plan.json') if len(parts)==4 and parts[3]=='plan' else load(job/'state.json'));return
   self.send_json({'error':'Not found'},404)
  except Exception as e:self.send_json({'error':str(e)},400)
 def do_POST(self):
  try:
   parts=urllib.parse.urlsplit(self.path).path.strip('/').split('/')
   if parts==['api','jobs']:
    data=self.body();mode=data.get('mode','run')
    if mode not in ('run','plan'):raise ValueError('Invalid mode')
    job=create(data['request']);QUEUE.enqueue(job,mode);self.send_json({'job_id':job.name,'status':'queued'},201);return
   if len(parts)==4 and parts[:2]==['api','jobs'] and parts[3]=='run':
    job=self.job(parts[2]);state=QUEUE.enqueue(job,'run');self.send_json({'status':state['status']});return
   if len(parts)==4 and parts[:2]==['api','jobs'] and parts[3]=='cancel':
    job=self.job(parts[2]);state=QUEUE.cancel(job);self.send_json({'status':state['status']});return
   self.send_json({'error':'Not found'},404)
  except Exception as e:self.send_json({'error':str(e)},400)
 def do_PUT(self):
  try:
   parts=urllib.parse.urlsplit(self.path).path.strip('/').split('/')
   if len(parts)!=4 or parts[:2]!=['api','jobs'] or parts[3]!='plan':raise ValueError('Invalid path')
   job=self.job(parts[2]);state=load(job/'state.json')
   if state['status']!='planned':raise ValueError('Plan can only be edited while job is planned and before rendering')
   plan=self.body();shots=plan.get('shots')
   if not isinstance(shots,list) or not shots:raise ValueError('Plan needs at least one shot')
   ids=[]
   for shot in shots:
    if not isinstance(shot,dict) or not all(isinstance(shot.get(k),str) and shot[k].strip() for k in ('id','narration','character','scene','action','prompt')):raise ValueError('Each shot needs id, narration, character, scene, action and prompt')
    if not shot['id'].startswith('shot-') or len(shot['id'])!=7 or not shot['id'][5:].isdigit():raise ValueError('Shot ids must be shot-01 through shot-99')
    ids.append(shot['id'])
   if len(set(ids))!=len(ids):raise ValueError('Shot ids must be unique')
   atomic(job/'plan.json',plan);self.send_json({'saved':True})
  except Exception as e:self.send_json({'error':str(e)},400)
def main():
 JOBS.mkdir(exist_ok=True);server=ThreadingHTTPServer(('127.0.0.1',PORT),Handler)
 threading.Thread(target=QUEUE.serve,daemon=True,name='film-dispatcher').start()
 print(f'Local film form: http://127.0.0.1:{PORT}',flush=True)
 if os.environ.get('LOCAL_FILM_OPEN_BROWSER')=='1':
  import webbrowser
  webbrowser.open(f'http://127.0.0.1:{PORT}')
 server.serve_forever()
if __name__=='__main__':main()
